/** Actual independently executed raw cumulative stage. */
type SkyMatchedScatteringOrder = 1 | 2 | 3 | 4 | 5 | 6;
/** Exact H parent plus explicit six-order execution and partial spectral scope. */
type SkyMatchedOrdersControl = DialOrdersControl &
	Readonly<{
		/** Absolute scientific cutoff; includes the run's mandatory finalization reserve. */ deadlineEpochMilliseconds: number;
	}>;
/** Complete original sparse union and local fixed-field reference index map. */
type SkyMatchedOrdersPlan = Readonly<{
	/** Original ordinary plan augmented with the original reference support. */ view: SkyViewPlan;
	/** Original six-rule independent quadrature and optical-depth prefixes. */ reference: SkyFixedFieldReferencePlan;
	/** Reference-local to captured-union indices. */ referenceIndexes: readonly number[];
}>;
/** Seven-method row whose order names the actual six-order recurrence stage. */
type SkyMatchedOrderRow = Omit<SkyContinuationProbeDiagnostic, 'order'> &
	Readonly<{
		/** Actual cumulative stage; never the temporary four-slot API address. */ order: SkyMatchedScatteringOrder;
	}>;
/** Exact mapping from the reused evaluator's temporary slot to a physical stage. */
type SkyMatchedOrderSlot = Readonly<{
	/** Original four-order evaluator or grouped density callback invocation. */ invocation:
		'original-four' | 'extension';
	/** Original evaluator slot, one through four. */ slot: number;
	/** Actual source fields supplied to the slot callback. */ actualOrder: SkyMatchedScatteringOrder;
	/** Duplicate N3/N4 slots prove parity rather than add new output rows. */ purpose: 'retained' | 'prefix-witness';
}>;
/** Explicit six-order component evidence carried through the host's bounded compiler extension. */
type SkyMatchedOrderDiagnostics = Readonly<{
	/** New schema, never sent to the original N4 diagnostic decoder. */ schemaId: 'sky-matched-order-diagnostics-v1';
	/** Explicit partial original C0 probe scope. */ scope: 'original-c0-probes-two-channels';
	/** Physical directional spectral radiance units. */ units: 'W m^-2 sr^-1 nm^-1';
	/** Actual channel, zero or eight. */ channel: number;
	/** Six actual raw recurrence stages. */ actualOrders: readonly SkyMatchedScatteringOrder[];
	/** Complete grouped seven-method inventory for every original probe/stage. */ rows: readonly SkyMatchedOrderRow[];
	/** Declared evaluator slot derivations, including duplicate prefix witnesses. */ slotDerivations: readonly SkyMatchedOrderSlot[];
	/** Independent fixed-field support locations, reused across all orders. */ queryCount: number;
	/** Independent prefix-column preparation count, charged once per prepared browser plan. */ preparationEvaluationCount: number;
	/** All first-four cumulative/grouped evaluations, including prefix-only outputs. */ prefixEvaluationCount: number;
	/** All extension slots, including the duplicate N3/N4 parity witnesses. */ extensionEvaluationCount: number;
	/** Sum of the preceding two actual field-evaluation counts. */ evaluationCount: number;
	/** Evaluations attributable to the retained grouped rows only. */ retainedEvaluationCount: number;
	/** Original first-four cumulative/grouped reference rows compared by digest. */ prefixReferenceRowCount: number;
	/** Number of repeated N3/N4 seven-method rows that were exactly equal. */ extensionPrefixComparisons: number;
	/** Fixed-field empirical admission remains distinct from recurrence and infinite-tail accuracy. */ allowancePolicy: string;
}>;
/** Exact original prefix identities plus reference-envelope and evaluator parity witnesses. */
type SkyMatchedOrdersPrefix = DialOrdersPrefixProof &
	Readonly<{
		/** Canonical JSON digest of every original cumulative/grouped seven-method row. */ referenceRowsSha256: string;
		/** Exact original row inventory count. */ referenceRowCount: number;
	}>;
/** Browser-only evaluated spectra, versioned diagnostic payload and original prefix rows. */
type SkyMatchedOrdersEvaluation = Readonly<{
	/** Original-selector spectra extended to six actual stages. */ evaluation: SkyOrderEvaluation;
	/** Strictly bounded six-order payload. */ diagnostics: SkyMatchedOrderDiagnostics;
	/** Original N1-N4 two-representation rows used only for exact prefix authentication. */ prefixRows: readonly SkyContinuationProbeDiagnostic[];
}>;
/** Authenticated original H prefix channel. */
type SkyMatchedOrdersParentChannel = Readonly<{
	/** Original channel. */ channel: number;
	/** Original reference-only unique query count. */ referenceQueryCount: number;
	/** Original independent prefix-column preparation work. */ referencePreparationEvaluationCount: number;
	/** Expected original field, spectrum and envelope identities. */ expected: SkyMatchedOrdersPrefix;
	/** Exact source artifacts supporting the comparison. */ identities: readonly DialFileIdentity[];
}>;
/** Read-only authenticated original H parent. */
type SkyMatchedOrdersParent = Readonly<{
	/** Exact immutable directory. */ run: string;
	/** Original unchanged recipe. */ control: SkyGpuControl;
	/** Original prefix authorities for channels zero/eight. */ channels: readonly SkyMatchedOrdersParentChannel[];
	/** Complete consumed parent identity list. */ identities: readonly DialFileIdentity[];
}>;
/** One held finite-order increment predicate, independent of capture admission. */
type SkyMatchedOrderPrediction = Readonly<{
	/** Stable original prediction address. */ id: string;
	/** Actual channel. */ channel: number;
	/** One of the two selected original physical rays. */ probeId: string;
	/** Available fifth-order increment, otherwise null. */ fifthIncrementWatts: number | null;
	/** Available sixth-order increment, otherwise null. */ sixthIncrementWatts: number | null;
	/** Propagated fifth increment's view allowance. */ fifthAllowanceWatts: number | null;
	/** Propagated sixth increment's view allowance. */ sixthAllowanceWatts: number | null;
	/** Actual outcome; no infinite-tail contraction claim. */ state: SkyVolumeCheckState;
}>;
/** Focused manufactured local verification, never a GPU run. */
type SkyMatchedOrdersProof = Readonly<{
	/** Versioned local proof. */ schemaId: string;
	/** Actual executed assertions. */ checks: number;
}>;
